CREATE TABLE IF NOT EXISTS campaigns (id CHAR(36) PRIMARY KEY,name VARCHAR(220) NOT NULL,slug VARCHAR(240) NOT NULL UNIQUE,description TEXT NOT NULL,category VARCHAR(120) NOT NULL,target_amount DECIMAL(18,2) NULL,collected_amount DECIMAL(18,2) NOT NULL DEFAULT 0,cover_url VARCHAR(1024) NULL,deadline DATETIME(6) NULL,status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX idx_campaign_status(status));
CREATE TABLE IF NOT EXISTS donations (id CHAR(36) PRIMARY KEY,campaign_id CHAR(36) NOT NULL,donor_user_id CHAR(36) NULL,donor_name VARCHAR(180) NULL,donor_email VARCHAR(254) NULL,anonymous BOOLEAN NOT NULL DEFAULT FALSE,message VARCHAR(1000) NULL,amount DECIMAL(18,2) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'WAITING_PAYMENT',payment_method VARCHAR(64) NOT NULL,idempotency_key VARCHAR(128) NOT NULL UNIQUE,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),INDEX idx_donation_campaign(campaign_id,status),CONSTRAINT fk_donation_campaign FOREIGN KEY(campaign_id) REFERENCES campaigns(id));
CREATE TABLE IF NOT EXISTS payment_proofs (id CHAR(36) PRIMARY KEY,donation_id CHAR(36) NOT NULL,object_key VARCHAR(512) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'PENDING',verified_by CHAR(36) NULL,verified_at DATETIME(6) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX idx_proof_donation(donation_id));
